int command_count() { return static_cast<int>(kCommandCount); }

const char* command_name(int index) {
  if (index < 0 || static_cast<std::size_t>(index) >= kCommandCount) return nullptr;
  return kCommands[index].name;
}

const char* command_args(int index) {
  if (index < 0 || static_cast<std::size_t>(index) >= kCommandCount) return "";
  return kCommands[index].args;
}

const char* command_summary(int index, int lang) {
  if (index < 0 || static_cast<std::size_t>(index) >= kCommandCount) return nullptr;
  if (lang < 0 || lang > 3) lang = 0;
  return kCommands[index].summary[lang];
}

const char* command_usage(int index, int lang) {
  if (index < 0 || static_cast<std::size_t>(index) >= kCommandCount) return nullptr;
  if (lang < 0 || lang > 3) lang = 0;
  return kCommands[index].usage[lang];
}

int command_index(const char* name) {
  if (name == nullptr) return -1;
  for (std::size_t i = 0; i < kCommandCount; ++i) {
    if (std::strcmp(kCommands[i].name, name) == 0) return static_cast<int>(i);
  }
  return -1;
}

int command_option_count(int index) {
  if (index < 0) return static_cast<int>(kGlobalOptionCount);
  if (static_cast<std::size_t>(index) >= kCommandCount) return 0;
  return static_cast<int>(kCommands[index].opt_count);
}

const char* command_option(int cmd, int opt, int lang) {
  if (lang < 0 || lang > 3) lang = 0;
  if (cmd < 0) {
    if (opt < 0 || static_cast<std::size_t>(opt) >= kGlobalOptionCount) return nullptr;
    return kGlobalOptions[opt].text[lang];
  }
  if (static_cast<std::size_t>(cmd) >= kCommandCount) return nullptr;
  const CmdRow& row = kCommands[cmd];
  if (opt < 0 || opt >= static_cast<int>(row.opt_count)) return nullptr;
  return kOptions[row.opt_begin + opt].text[lang];
}

